(()=>{'use strict';const $=s=>document.querySelector(s),L=KitchenLife,canvas=$('#kitchen'),g=canvas.getContext('2d'),art=new KitchenArt(g),motion=matchMedia('(prefers-reduced-motion: reduce)');let state,returning=false;try{const raw=localStorage.getItem(L.KEY);returning=!!raw;state=L.decode(raw)}catch{state=L.create()}
let w=0,h=0,last=0,time=0,bottom=0,flight=null,batch=null,pulse=0,folds=state.folds,messageUntil=0,buyingSeeds=false;
class KitchenAudio extends PondAudio{player(name){if(this.players.has(name))return this.players.get(name);const player=super.player(name);player.src=new URL('../pond/'+(name==='rain'?'rain-seamless.wav':'mixkit-night-crickets-near-the-swamp-1782.wav'),location.href).href;return player}}
const audio=new KitchenAudio(settings=>{state.settings.audio=settings;save();syncAudio()},text=>{$('#audio-status').textContent=text},()=>syncAudio());audio.enabled={...state.settings.audio};audio.setVolume(state.settings.rainVolume);
function save(){try{localStorage.setItem(L.KEY,JSON.stringify(state));void syncSeeds();return true}catch{$('#save-note').textContent='Saving is unavailable in this browser.';$('#seed-status').textContent='Enable browser storage to save your sales and seeds.';return false}}
function syncSeeds(note=''){
 const result=SlotsLife.kitchenWallet(localStorage,L),button=$('#buy-seeds');
 if(result.status==='current'){
  $('#coin-balance').textContent=result.coins.toLocaleString()+' coins';
  $('#seed-balance').textContent=result.balance.toLocaleString()+' seeds in Golden Seed';
  button.disabled=buyingSeeds||result.coins<10;
  $('#seed-status').textContent=note||(result.coins<10?`${10-result.coins} more coin${10-result.coins===1?'':'s'} for 10 seeds.`:'1 coin buys 1 seed.');
 }else{button.disabled=true;$('#coin-balance').textContent='Coins unavailable';$('#seed-status').textContent='Could not read your wallet. Your coins have not been spent.'}
}
$('#buy-seeds').onclick=async()=>{
 if(buyingSeeds||!save())return;buyingSeeds=true;syncSeeds();let note='';
 try{
  const purchase=()=>SlotsLife.buyKitchenSeeds(localStorage,L,10);
  const result=await(navigator.locks?.request?navigator.locks.request('spriggan-seed-wallet',purchase):Promise.resolve().then(purchase));
  note=result.status==='bought'?'10 seeds added to Golden Seed.':result.status==='insufficient'?'You need 10 coins to buy 10 seeds.':'Could not save the purchase. Your coins have not been spent.';
 }catch{note='Could not save the purchase. Your coins have not been spent.'}
 finally{buyingSeeds=false;syncSeeds(note)}
};
window.addEventListener('storage',e=>{if(e.key===SlotsLife.KEY)void syncSeeds()});

function syncAudio(){for(const id of ['ambient','music'])$('#'+id).setAttribute('aria-pressed',String(audio.enabled[id]));$('#rainfx').setAttribute('aria-pressed',String(audio.enabled.rain));$('#rainfx').textContent=audio.enabled.rain?'Remove rain':'Add rain';$('#resume-audio').hidden=!audio.needsResume;if(!audio.needsResume)$('#audio-status').textContent='';if(w&&h&&state.paused)draw()}
function hint(){if(state.paused)return'The kitchen can wait.';if(state.ready)return'Lift the lid to put these on the shop counter.';if(state.basket.length===6)return'A full basket of little folds. Time to steam.';if(state.stage==='filled')return['A little pinch. Then another.','One fold, softly done.','One last fold to tuck it in.'][state.folds];if(state.stage==='wrapper')return'A spoonful of something good.';if(state.cooking.length)return'Let the steam do its work. Nothing will burn.';return state.shop.guests.some(c=>c.phase==='waiting')?'Your guests are in no hurry. Make something warm.':'Start with a little circle of dough.'}
function message(text){$('#kitchen-status').textContent=text;messageUntil=performance.now()+4500}
// Scene framing stays fixed when either control panel opens.
function measure(){bottom=h-(w<700?115:100)}
new ResizeObserver(()=>requestAnimationFrame(()=>{measure();draw()})).observe($('#pomodoro'));
function sync(){document.body.dataset.night=state.settings.night;$('#night').textContent=state.settings.night?'Lantern glow':'Late night';$('#night').setAttribute('aria-pressed',String(state.settings.night));$('#pause').textContent=state.paused?'Resume kitchen':'Pause kitchen';$('#pause').setAttribute('aria-pressed',String(state.paused));$('#rainvol').value=state.settings.rainVolume;$('#rainvol-value').textContent=state.settings.rainVolume+'%';$('#served-count').textContent=`${state.shop.sales} dumplings sold`;$('#shop-status').textContent=`${state.shop.guests.filter(c=>c.phase==='waiting'||c.phase==='arriving').length} guests waiting · ${state.plate.length} on the counter`;$('#make').textContent=state.stage==='empty'?'Lay a wrapper ＋':state.stage==='wrapper'?'Add the filling':'Fold gently · '+(state.folds+1)+'/3';$('#make').disabled=state.paused||state.basket.length>=6||!!flight||!!batch;$('#steamer').textContent=state.ready?(state.plate.length+state.cooking.length>24?'Counter is full':'Lift the lid & serve'):state.cooking.length?'Steaming quietly…':state.basket.length?`Steam ${Math.min(6,state.basket.length)} little fold${state.basket.length===1?'':'s'}`:'Basket is empty';$('#steamer').disabled=state.paused||(state.ready&&state.plate.length+state.cooking.length>24)||(!state.ready&&(!state.basket.length||!!state.cooking.length))||!!flight||!!batch;for(const b of document.querySelectorAll('[data-filling]')){b.setAttribute('aria-pressed',String(b.dataset.filling===state.filling));b.disabled=state.stage==='filled'||state.paused||!!flight||!!batch}if(!messageUntil)$('#kitchen-status').textContent=hint();measure()}
function make(){if(flight||batch)return;const event=L.make(state);if(!event)return;pulse=1;if(event==='folded'){folds=0;if(!motion.matches)flight={age:0,target:state.cooking.length?'tray':'basket',index:state.basket.length-1};message('A little fold, made by you.')}else if(event==='wrapper'){folds=0;message('A small beginning. Choose your filling.')}else message(hint());save();sync();draw()}
function steamer(){if(flight||batch||state.paused)return;const before=structuredClone(state);if(state.ready){if(!L.serve(state))return;const refill=state.basket.length>0;if(refill)L.steam(state);if(!motion.matches)batch={age:0,before,refill,duration:1.35+(refill?1.35:0)};message(refill?'A fresh batch takes its place.':'On the counter, ready for your guests.')}else if(L.steam(state)){message('A little steam. A little patience.')}else return;save();sync();draw()}

$('#make').onclick=make;$('#steamer').onclick=steamer;for(const b of document.querySelectorAll('[data-filling]'))b.onclick=()=>{if(state.stage==='filled'||state.paused||flight||batch)return;state.filling=b.dataset.filling;save();sync();draw()};
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,{board,basket}=art.layout;if(!board)return;if(Math.abs(x-board.x)<150*board.k&&Math.abs(y-board.y)<80*board.k)make();else if(Math.abs(x-basket.x)<110*basket.k&&Math.abs(y-basket.y)<80*basket.k)steamer()});
const panel=$('.ambience'),trigger=$('#toggle-controls');function collapse(open){trigger.setAttribute('aria-expanded',String(open));trigger.setAttribute('aria-label',open?'Close shop controls':'Open shop controls');$('#ambience-controls').hidden=!open}trigger.onclick=()=>collapse(trigger.getAttribute('aria-expanded')!=='true');$('.kitchen-note').onclick=()=>{collapse(true);$('#buy-seeds').scrollIntoView({block:'nearest'});trigger.focus()};document.addEventListener('click',e=>{if(!panel.contains(e.target)&&!e.target.closest('.kitchen-note'))collapse(false)});
$('#pause').onclick=()=>{state.paused=!state.paused;message(state.paused?'The kitchen can wait.':'Back to a little making.');save();sync();draw()};$('#night').onclick=()=>{state.settings.night=!state.settings.night;save();sync();draw()};$('#rainvol').oninput=e=>{state.settings.rainVolume=Number(e.target.value);audio.setVolume(state.settings.rainVolume);save();sync()};for(const [id,name] of [['rainfx','rain'],['ambient','ambient'],['music','music']])$('#'+id).onclick=()=>audio.toggle(name,!audio.enabled[name]);$('#resume-audio').onclick=()=>audio.resume();
document.addEventListener('pointerdown',e=>{if(!panel.contains(e.target)&&audio.needsResume)audio.resume()},{passive:true});document.addEventListener('keydown',e=>{if(e.key==='Escape'){collapse(false);return}if(/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();$('#pause').click()}if(audio.needsResume)audio.resume()});
function draw(){art.render(w,h,state,motion.matches?0:time,{bottom,pulse:motion.matches?0:pulse,flight,batch,folds:motion.matches?state.folds:folds,rain:audio.enabled.rain?(ctx,win,t)=>{ctx.save();ctx.translate(win.x,win.y);MapRain.prototype.draw.call({enabled:true,reduced:motion.matches,style:'kitchen'},ctx,win.w,win.h,t,{night:state.settings.night});ctx.restore()}:null})}
function step(dt){if(state.paused)return;time+=dt;if(batch){batch.age+=dt;if(batch.age>=batch.duration){batch=null;sync()}}pulse=Math.max(0,pulse-dt*2);folds+=(state.folds-folds)*(1-Math.exp(-dt*9));if(flight){flight.age+=dt;if(flight.age>=.85){flight=null;sync()}}const salesBefore=state.shop.sales;const reserved=batch&&batch.age<1.35?batch.before.cooking.filter((_,i)=>batch.age<i*.09+.8).length:0;if(L.step(state,dt,reserved)){message('The lid is warm. Your dumplings are ready.');save();sync()}if(state.shop.sales!==salesBefore){const guest=state.shop.guests.find(c=>c.phase==='paying'&&c.age===0);message(`${guest?.name||'A neighbor'} ${guest?.takeaway?'picked up a takeaway box':'bought a dumpling'}. +${(state.shop.sales-salesBefore)*3} coins.`);save();sync()}}
function resize(){w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);g.setTransform(d,0,0,d,0,0);measure();draw()}
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;if(!document.hidden){step(dt);if(!state.paused)draw();if(messageUntil&&now>messageUntil){messageUntil=0;$('#kitchen-status').textContent=hint()}}requestAnimationFrame(frame)}
SprigganRuntime.runBackground(step,save,()=>state.paused);window.addEventListener('resize',resize);window.addEventListener('pagehide',()=>{save();audio.visibility(true)});window.addEventListener('pageshow',()=>audio.visibility(document.hidden&&SprigganRuntime.mobile));document.addEventListener('visibilitychange',()=>{last=performance.now();save();audio.visibility(document.hidden&&SprigganRuntime.mobile)});motion.addEventListener('change',()=>{if(motion.matches){flight=null;batch=null;}sync();draw()});setInterval(()=>{save();sync()},5000);$('#memory').textContent=returning?'Welcome back. There’s a place for you here.':'A quiet kitchen, saved on this device.';sync();syncAudio();save();resize();requestAnimationFrame(frame);
})();
